UPDATE orders
   SET status = 'BILLED'
 WHERE status = 'NEW';

COMMIT;

DECLARE
  l_rows PLS_INTEGER;
BEGIN
  LOOP
    UPDATE orders
       SET status = 'BILLED'
     WHERE status = 'NEW'
       AND ROWNUM <= 10000;

    l_rows := SQL%ROWCOUNT;
    COMMIT;

    EXIT WHEN l_rows = 0;
  END LOOP;
END;
/

